def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate the solid horizontal separator.
    sep = next(
        (r for r, row in enumerate(g)
         if len(set(row)) == 1 and row[0] != g[0][0]),
        None
    )
    if sep is None:
        return g
    line_color = g[sep][0]
    background = g[0][0]

    points = [
        (r, c)
        for r in range(h)
        for c in range(w)
        if r != sep and g[r][c] not in (background, line_color)
    ]
    if not points:
        return g

    top = min(r for r, _ in points)
    bottom = max(r for r, _ in points)

    if bottom < sep:  # Figure above separator: move it down against the line.
        shift = sep - 1 - bottom
        new_points = [(r + shift, c) for r, c in points]
        marker_row = top + shift - 1
    else:  # Figure below separator: move it up against the line.
        shift = sep + 1 - top
        new_points = [(r + shift, c) for r, c in points]
        marker_row = bottom + shift + 1

    # Clear the original figure, then place it in its new position.
    for r, c in points:
        g[r][c] = background
    for r, c in new_points:
        g[r][c] = grid[top if False else r - shift][c]

    if 0 <= marker_row < h:
        g[marker_row] = [8] * w
    return g
